evidence.command:
set -e; D=$(mktemp -d); ln -s ~/.volta/tools/image/packages/@deepseek-ai/dsh/lib/node_modules/@deepseek-ai/dsh/node_modules "$D/node_modules"; cat > "$D/probe.mjs" <<'PROBE'
import { Context } from '@deepseek-ai/cordis';
import WorkerThreadCodeRuntime from '@deepseek-ai/dsh-code-runtime-worker-thread';
import LocalSandboxProvider from '@deepseek-ai/dsh-sandbox-local';
import { rmSync, existsSync, mkdtempSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
const work = mkdtempSync(join(tmpdir(), 'm0-4-'));
const ctx = new Context();
ctx.plugin(LocalSandboxProvider, {});
ctx.plugin(WorkerThreadCodeRuntime, {});
await new Promise(r => setTimeout(r, 400));
const bashTarget = join(work, 'bash-probe.txt');
const confined = ctx.sandbox.confine(['/bin/sh','-c',`echo BASH > ${JSON.stringify(bashTarget)}`], { mode:'read-only', workspaceRoot: work });
console.log('A_sandbox_runner=' + confined.argv[0].split('/').pop());
console.log('A_sandbox_enforcement=' + confined.enforcement);
const r = spawnSync(confined.argv[0], confined.argv.slice(1), { encoding:'utf8' });
console.log('A_bash_exit_nonzero=' + (r.status !== 0));
console.log('A_bash_stderr_matches_denial_signature=' + confined.denialSignatures.some(s => (r.stderr ?? '').toLowerCase().includes(s.toLowerCase())));
console.log('A_bash_file_written=' + existsSync(bashTarget));
const codeTarget = join(work, 'code-probe.txt');
const program = `
const out = {};
try { require('node:fs'); out.require_in_scope = 'yes'; }
catch (e) { out.require_in_scope = e.name + ': ' + e.message; }
const fs = await import('node:fs');
out.dynamic_import_node_fs = 'ok';
fs.writeFileSync(${JSON.stringify(codeTarget)}, 'WRITTEN_BY_RUN_CODE');
out.read_back = fs.readFileSync(${JSON.stringify(codeTarget)}, 'utf8');
out.env_key_count = Object.keys(process.env).length;
out.pid = process.pid;
return out;
`;
const res = await ctx.codeRuntime.run({ program, bindings: [], signal: new AbortController().signal });
const v = res.value ?? {};
console.log('B_runtime_language=' + ctx.codeRuntime.language);
console.log('B_runtime_isolation=' + ctx.codeRuntime.isolation);
console.log('B_run_error=' + JSON.stringify(res.error ?? null));
console.log('B_require_in_scope=' + v.require_in_scope);
console.log('B_dynamic_import_node_fs=' + v.dynamic_import_node_fs);
console.log('B_read_back=' + v.read_back);
console.log('B_process_env_key_count=' + v.env_key_count);
console.log('B_program_pid_equals_host_pid=' + (v.pid === process.pid));
console.log('B_code_file_written=' + existsSync(codeTarget));
rmSync(work, { recursive:true, force:true });
await ctx.stop?.();
process.exit(0);
PROBE
cd "$D" && node --no-warnings "$D/probe.mjs" > /tmp/m0-4-verify.txt 2>&1; cat /tmp/m0-4-verify.txt; rm -rf "$D"
